export default async function install(app){
  const cfg=app.config, F=cfg.fields, SV=cfg.severityValues, CF=cfg.casualtyFields;
  const layer=app.layers[cfg.layerId]; app.assert(layer,'Collision layer not found'); await layer.load();
  layer.minScale=0; layer.outFields=['*']; layer.title='RSA Road Collisions 2016–2024';
  const COLORS={Fatal:'#7f1d1d',Serious:'#f97316','Minor injury':'#facc15'};
  const incidentToLabel=Object.fromEntries(Object.entries(SV).map(([k,v])=>[v,k]));
  const esc=s=>String(s).replaceAll("'","''");
  const lit=s=>"'"+esc(s)+"'";
  const pointRenderer={type:'unique-value',field:F.severity,defaultSymbol:{type:'simple-marker',style:'circle',size:5,color:'#9ca3af',outline:{color:'#fff',width:.5}},uniqueValueInfos:[{value:SV['Minor injury'],label:'Minor injury collisions',symbol:{type:'simple-marker',style:'circle',size:6,color:COLORS['Minor injury'],outline:{color:'#5f4b00',width:.5}}},{value:SV.Serious,label:'Serious collisions',symbol:{type:'simple-marker',style:'circle',size:9,color:COLORS.Serious,outline:{color:'#7c2d12',width:.75}}},{value:SV.Fatal,label:'Fatal collisions',symbol:{type:'simple-marker',style:'circle',size:13,color:COLORS.Fatal,outline:{color:'#fff',width:1.25}}}]};
  const heatRenderer={type:'heatmap',radius:18,colorStops:[{ratio:0,color:'rgba(255,255,178,0)'},{ratio:.25,color:'#fee08b'},{ratio:.55,color:'#f97316'},{ratio:.85,color:'#dc2626'},{ratio:1,color:'#7f1d1d'}],maxDensity:0.02,minDensity:0};
  const cluster={type:'cluster',clusterRadius:'70px',maxScale:50000,popupTemplate:{title:'Cluster of {cluster_count} collisions',content:[{type:'fields',fieldInfos:[{fieldName:'cluster_count',label:'Total collisions'},{fieldName:'fatal_count',label:'Fatal'},{fieldName:'serious_count',label:'Serious'},{fieldName:'minor_count',label:'Minor injury'}]}]},fields:[{name:'fatal_count',statisticType:'sum',onStatisticField:`CASE WHEN ${F.severity} = '${esc(SV.Fatal)}' THEN 1 ELSE 0 END`},{name:'serious_count',statisticType:'sum',onStatisticField:`CASE WHEN ${F.severity} = '${esc(SV.Serious)}' THEN 1 ELSE 0 END`},{name:'minor_count',statisticType:'sum',onStatisticField:`CASE WHEN ${F.severity} = '${esc(SV['Minor injury'])}' THEN 1 ELSE 0 END`}],labelingInfo:[{labelExpressionInfo:{expression:"Text($feature.cluster_count, '#,###')"},symbol:{type:'text',color:'#111827',haloColor:'#fff',haloSize:1,font:{size:11,weight:'bold'}},labelPlacement:'center-center'}]};
  function casualtyRows(a){const rows=[]; for(const [u,m] of Object.entries(CF)) for(const [inj,field] of Object.entries(m)){const v=Number(a[field]||0); if(v) rows.push([u,inj,v]);} return rows;}
  layer.renderer=pointRenderer; layer.featureReduction=cluster; layer.orderBy=[{valueExpression:`When($feature.${F.severity} == '${SV.Fatal}', 3, $feature.${F.severity} == '${SV.Serious}', 2, 1)`,order:'ascending'}]; layer.popupTemplate={title:`Collision {${F.id}}`,content:(e)=>{const a=e.graphic.attributes, div=document.createElement('div'); const p=document.createElement('p'); p.textContent=`${incidentToLabel[a[F.severity]]||a[F.severity]} · ${a[F.year]} · ${a[F.month]||''} · ${a[F.timeBand]||''}`; div.append(p); const p2=document.createElement('p'); p2.textContent=`${a[F.county]||''} · ${a[F.localAuthority]||''}`; div.append(p2); const rows=casualtyRows(a); if(rows.length){const t=document.createElement('calcite-table'); t.caption='Road users by injury type'; t.scale='s'; const hr=document.createElement('calcite-table-row'); hr.slot='table-header'; ['Road user','Injury','Persons'].forEach(h=>{const c=document.createElement('calcite-table-header'); c.textContent=h; hr.append(c)}); t.append(hr); rows.forEach(r=>{const tr=document.createElement('calcite-table-row'); r.forEach(v=>{const c=document.createElement('calcite-table-cell'); c.textContent=String(v); tr.append(c)}); t.append(tr)}); div.append(t);} else {const z=document.createElement('p'); z.textContent='No casualty counts recorded for this collision.'; div.append(z);} return div;}};
  const header=app.getMount('collision-header'), filters=app.getMount('collision-filters'), dash=app.getMount('collision-dashboard');
  const style=document.createElement('style'); style.textContent=`.rc-root{font:inherit;color:var(--app-text);display:flex;flex-direction:column;gap:var(--app-gap)}.rc-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.rc-card{background:var(--app-surface-raised);border:1px solid var(--app-border);border-radius:var(--app-radius);padding:10px;min-width:0}.rc-kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.rc-kpi b{font-size:1.45rem;display:block}.rc-chart{height:170px}.rc-chart svg{width:100%;height:100%;overflow:hidden;display:block}.rc-muted{color:var(--app-text-muted);font-size:.85rem}.rc-click{cursor:pointer}.rc-loader{min-height:40px}.rc-chip{border:1px solid var(--app-border);border-radius:999px;padding:5px 9px;background:var(--app-surface);cursor:pointer}.rc-chip[aria-pressed=true]{background:var(--app-accent);color:var(--app-accent-label)}@media(max-width:900px){.rc-kpis{grid-template-columns:1fr}.rc-chart{height:145px}}`; document.head.append(style); app.onCleanup(()=>style.remove());
  let meta={years:[],counties:[],countyLA:new Map()}, state={counties:[],las:[],years:null,types:[],heat:false}, busy=0, timer=null, rev=0;
  const allTypes=()=>!state.types.length; const selectedYears=()=>state.years||[meta.minYear,meta.maxYear];
  function make(tag,cls,txt){const el=document.createElement(tag); if(cls) el.className=cls; if(txt!=null) el.textContent=txt; return el}
  function where(){const w=['1=1']; if(state.counties.length) w.push(`${F.county} IN (${state.counties.map(lit).join(',')})`); if(state.las.length) w.push(`${F.localAuthority} IN (${state.las.map(lit).join(',')})`); if(state.years){const ys=[]; for(let y=state.years[0];y<=state.years[1];y++) ys.push(lit(y)); w.push(`${F.year} IN (${ys.join(',')})`)} if(state.types.length) w.push(`${F.severity} IN (${state.types.map(t=>lit(SV[t])).join(',')})`); return w.join(' AND ')}
  function qBase(){const q=layer.createQuery(); q.where=where(); q.returnGeometry=false; return q}
  function stat(name,field,typ='sum'){return {statisticType:typ,onStatisticField:field,outStatisticFieldName:name}}
  function sumExpr(fields){return fields.join(' + ')}
  const fatalFields=Object.values(CF).map(m=>m.Fatal), seriousFields=Object.values(CF).map(m=>m['Serious injury']), minorFields=Object.values(CF).map(m=>m['Minor injury']);
  async function grouped(group,stats,order){const q=qBase(); q.groupByFieldsForStatistics=[group]; q.outStatistics=stats; if(order) q.orderByFields=[order]; const r=await layer.queryFeatures(q); return r.features.map(f=>f.attributes)}
  async function totals(){const q=qBase(); q.outStatistics=[stat('collisions',layer.objectIdField,'count'),stat('fatalities',sumExpr(fatalFields)),stat('serious',sumExpr(seriousFields)),stat('minor',sumExpr(minorFields))]; return (await layer.queryFeatures(q)).features[0]?.attributes||{} }
  async function loadMeta(){const q=layer.createQuery(); q.where='1=1'; q.returnGeometry=false; q.groupByFieldsForStatistics=[F.county,F.localAuthority]; q.outStatistics=[stat('n',layer.objectIdField,'count')]; const r=await layer.queryFeatures(q); const cm=new Map(); r.features.forEach(f=>{const a=f.attributes,c=a[F.county],l=a[F.localAuthority]; if(!c||!l) return; if(!cm.has(c)) cm.set(c,new Set()); cm.get(c).add(l)}); meta.counties=[...cm.keys()].sort(); meta.countyLA=new Map([...cm].map(([k,v])=>[k,[...v].sort()])); const y=await grouped(F.year,[stat('n',layer.objectIdField,'count')],`${F.year} ASC`); meta.years=y.map(a=>Number(a[F.year])).filter(Number.isFinite).sort((a,b)=>a-b); meta.minYear=meta.years[0]; meta.maxYear=meta.years.at(-1);}
  function setBusy(v){busy+=v?1:-1; [filters,dash,header].forEach(m=>m.toggleAttribute('aria-busy',busy>0));}
  function toURL(){const p=new URLSearchParams(); if(state.counties.length)p.set('county',state.counties.join('|')); if(state.las.length)p.set('la',state.las.join('|')); if(state.years)p.set('years',state.years.join('-')); if(state.types.length)p.set('type',state.types.join('|')); if(state.heat)p.set('view','heat'); history.replaceState(null,'','?'+p.toString());}
  function fromURL(){const p=new URLSearchParams(location.search); if(p.get('county')) state.counties=p.get('county').split('|').filter(Boolean); if(p.get('la')) state.las=p.get('la').split('|').filter(Boolean); if(p.get('years')){const a=p.get('years').split('-').map(Number); if(a.length===2&&a.every(Number.isFinite)) state.years=a;} if(p.get('type')) state.types=p.get('type').split('|').filter(t=>SV[t]); state.heat=p.get('view')==='heat';}
  function validLAs(){return state.counties.length?[...new Set(state.counties.flatMap(c=>meta.countyLA.get(c)||[]))].sort():[...new Set([...meta.countyLA.values()].flat())].sort()}
  function enforceLA(){const ok=new Set(validLAs()); state.las=state.las.filter(x=>ok.has(x));}
  function combobox(label,values,selected,onChange){const wrap=make('calcite-label',null,label), cb=document.createElement('calcite-combobox'); cb.selectionMode='multiple'; cb.placeholder='All'; cb.setAttribute('aria-label',label); values.forEach(v=>{const it=document.createElement('calcite-combobox-item'); it.value=v; it.textLabel=v; it.selected=selected.includes(v); cb.append(it)}); cb.addEventListener('calciteComboboxChange',()=>{onChange([...cb.selectedItems].map(i=>i.value)); schedule()}); wrap.append(cb); return wrap;}
  function renderFilters(){enforceLA(); filters.replaceChildren(); const root=make('div','rc-root'); root.append(combobox('County',meta.counties,state.counties,v=>{state.counties=v;enforceLA();renderFilters()})); root.append(combobox('Local Authority',validLAs(),state.las,v=>state.las=v)); const lab=make('calcite-label',null,'Year range'); const sl=document.createElement('calcite-slider'); sl.min=meta.minYear; sl.max=meta.maxYear; sl.step=1; sl.minValue=selectedYears()[0]; sl.maxValue=selectedYears()[1]; sl.ticks=2; sl.labelHandles=true; sl.addEventListener('calciteSliderChange',()=>{state.years=[Number(sl.minValue),Number(sl.maxValue)]; if(state.years[0]===meta.minYear&&state.years[1]===meta.maxYear) state.years=null; schedule()}); lab.append(sl); root.append(lab); const allY=document.createElement('calcite-button'); allY.textContent='All years'; allY.appearance='outline'; allY.onclick=()=>{state.years=null;renderFilters();schedule()}; root.append(allY); const chips=make('div','rc-row'); ['All','Fatal','Serious','Minor injury'].forEach(t=>{const b=document.createElement('calcite-button'); b.textContent=t; b.scale='s'; b.appearance=(t==='All'?allTypes():state.types.includes(t))?'solid':'outline'; b.setAttribute('aria-pressed',t==='All'?String(allTypes()):String(state.types.includes(t))); b.onclick=()=>{if(t==='All') state.types=[]; else {state.types=state.types.includes(t)?state.types.filter(x=>x!==t):[...state.types,t];} renderFilters(); schedule()}; chips.append(b)}); root.append(make('div','rc-muted','Collision Type')); root.append(chips); const sw=document.createElement('calcite-switch'); sw.checked=state.heat; sw.addEventListener('calciteSwitchChange',()=>{state.heat=sw.checked; applyViewMode(); schedule(false)}); const swl=make('calcite-label',null,'Heatmap view'); swl.append(sw); root.append(swl); filters.append(root)}
  function renderHeader(t){header.replaceChildren(); const root=make('div','rc-root'); const row=make('div','rc-row'); const summary=[]; if(state.counties.length) summary.push(`${state.counties.length} county filter${state.counties.length>1?'s':''}`); if(state.las.length) summary.push(`${state.las.length} local authority filter${state.las.length>1?'s':''}`); if(state.years) summary.push(`${state.years[0]}–${state.years[1]}`); if(state.types.length) summary.push(state.types.join(', ')); row.append(make('strong',null,`Road Collisions in Ireland · ${meta.minYear}–${meta.maxYear}`)); row.append(make('span','rc-muted',summary.length?summary.join(' · '):'All records')); const reset=document.createElement('calcite-button'); reset.textContent='Reset filters'; reset.scale='s'; reset.onclick=()=>{state={counties:[],las:[],years:null,types:[],heat:false}; applyViewMode(); renderFilters(); schedule()}; row.append(reset); const bm=document.createElement('calcite-button'); bm.textContent='Toggle imagery'; bm.scale='s'; bm.appearance='outline'; bm.onclick=()=>{app.map.basemap=app.map.basemap?.id==='satellite'?'gray-vector':'satellite'}; row.append(bm); if(t) row.append(make('span','rc-muted',`${Number(t.collisions||0).toLocaleString()} collisions selected`)); root.append(row); header.append(root)}
  function applyViewMode(){layer.renderer=state.heat?heatRenderer:pointRenderer; layer.featureReduction=state.heat?null:cluster; toURL()}
  function chart(title,rows,opt){const card=make('div','rc-card'), h=make('strong',null,title); card.append(h); if(opt.foot) card.append(make('div','rc-muted',opt.foot)); const box=make('div','rc-chart'); if(!rows.length||!rows.some(r=>r.total>0)){box.append(make('p','rc-muted','No results for the current filters.')); card.append(box); return card;} const W=360,H=140,L=92,B=24, max=Math.max(...rows.map(r=>r.total),1), svg=document.createElementNS('http://www.w3.org/2000/svg','svg'); svg.setAttribute('viewBox',`0 0 ${W} ${H}`); svg.setAttribute('preserveAspectRatio','none'); rows.forEach((r,i)=>{const y=12+i*((H-28)/rows.length), bh=Math.max(8,(H-36)/rows.length-4); let x=L; (r.parts||[{k:'Total',v:r.total,c:'var(--app-series-1)'}]).forEach(p=>{const w=(W-L-10)*p.v/max; const rect=document.createElementNS(svg.namespaceURI,'rect'); rect.setAttribute('x',x); rect.setAttribute('y',y); rect.setAttribute('width',Math.max(0,w)); rect.setAttribute('height',bh); rect.setAttribute('fill',p.c); rect.classList.add('rc-click'); rect.addEventListener('click',()=>opt.click&&opt.click(r,p)); svg.append(rect); x+=w}); const tx=document.createElementNS(svg.namespaceURI,'text'); tx.setAttribute('x',0); tx.setAttribute('y',y+bh-1); tx.setAttribute('font-size','10'); tx.setAttribute('fill','currentColor'); tx.textContent=String(r.label).slice(0,22); svg.append(tx); const val=document.createElementNS(svg.namespaceURI,'text'); val.setAttribute('x',L+4+(W-L-10)*r.total/max); val.setAttribute('y',y+bh-1); val.setAttribute('font-size','10'); val.setAttribute('fill','currentColor'); val.textContent=Number(r.total||0).toLocaleString(); svg.append(val)}); box.append(svg); card.append(box); return card}
  const monthOrder=['January','February','March','April','May','June','July','August','September','October','November','December'];
  function timeSort(v){const m=String(v).match(/(\d{1,2})/); return m?Number(m[1]):99}
  async function refresh(){const my=++rev; setBusy(true); try{layer.definitionExpression=where(); toURL(); const stats=[stat('fatal',`CASE WHEN ${F.severity} = '${esc(SV.Fatal)}' THEN 1 ELSE 0 END`),stat('serious',`CASE WHEN ${F.severity} = '${esc(SV.Serious)}' THEN 1 ELSE 0 END`),stat('minor',`CASE WHEN ${F.severity} = '${esc(SV['Minor injury'])}' THEN 1 ELSE 0 END`)]; const roadStats=[]; for(const [u,m] of Object.entries(CF)) for(const [inj,field] of Object.entries(m)) roadStats.push(stat((u+'_'+inj).replace(/[^A-Za-z0-9]/g,'_'),field)); const [t,yr,mo,tb,road,places]=await Promise.all([totals(),grouped(F.year,stats),grouped(F.month,[stat('n',layer.objectIdField,'count')]),grouped(F.timeBand,[stat('n',layer.objectIdField,'count')]),(async()=>{const q=qBase(); q.outStatistics=roadStats; return (await layer.queryFeatures(q)).features[0]?.attributes||{}})(),grouped(state.counties.length?F.localAuthority:F.county,[stat('n',layer.objectIdField,'count')])]); if(my!==rev)return; renderHeader(t); renderDashboard(t,yr,mo,tb,road,places); }catch(e){dash.replaceChildren(notice('danger','Query error',e.message||String(e))); app.reportError(e);} finally{setBusy(false)}}
  function notice(kind,title,msg){const n=document.createElement('calcite-notice'); n.kind=kind; n.open=true; const a=make('div',null,title); a.slot='title'; const b=make('div',null,msg); b.slot='message'; n.append(a,b); return n}
  function renderDashboard(t,yr,mo,tb,road,places){dash.replaceChildren(); const root=make('div','rc-root'); const k=make('div','rc-kpis'); [['Total collisions',t.collisions],['Fatalities (persons)',t.fatalities],['Serious injuries (persons)',t.serious],['Minor injuries (persons)',t.minor]].forEach(([a,v])=>{const c=make('div','rc-card rc-kpi'); c.append(make('span','rc-muted',a),make('b',null,Number(v||0).toLocaleString())); k.append(c)}); root.append(k); const pre2020=selectedYears()[1]<2020; root.append(chart('Collisions by year',yr.map(a=>({label:a[F.year],total:(a.fatal||0)+(a.serious||0)+(a.minor||0),parts:[{k:'Fatal',v:a.fatal||0,c:COLORS.Fatal},{k:'Serious',v:a.serious||0,c:COLORS.Serious},{k:'Minor',v:a.minor||0,c:COLORS['Minor injury']}]})),{click:r=>{state.years=[Number(r.label),Number(r.label)];renderFilters();schedule()}})); root.append(chart('Collisions by month',mo.sort((a,b)=>monthOrder.indexOf(a[F.month])-monthOrder.indexOf(b[F.month])).map(a=>({label:a[F.month],total:a.n||0})),{click:r=>{}})); root.append(chart('Collisions by 4-hour time band',tb.sort((a,b)=>timeSort(a[F.timeBand])-timeSort(b[F.timeBand])).map(a=>({label:a[F.timeBand],total:a.n||0})),{click:r=>{}})); const roadRows=Object.keys(CF).map(u=>{const m=CF[u], get=inj=>road[(u+'_'+inj).replace(/[^A-Za-z0-9]/g,'_')]||0; const na=u==='E-scooter user/Other'&&pre2020; return {label:u,total:na?0:get('Fatal')+get('Serious injury')+get('Minor injury'),parts:na?[]:[{k:'Fatal',v:get('Fatal'),c:COLORS.Fatal},{k:'Serious',v:get('Serious injury'),c:COLORS.Serious},{k:'Minor',v:get('Minor injury'),c:COLORS['Minor injury']}],na};}); root.append(chart('Casualties by road user type',roadRows,{foot:pre2020?'E-scooter user/Other is n/a because all selected years are before 2020.':'',click:null})); root.append(chart(`Top 10 ${state.counties.length?'local authorities':'counties'} by collisions`,places.sort((a,b)=>(b.n||0)-(a.n||0)).slice(0,10).map(a=>({label:a[state.counties.length?F.localAuthority:F.county],total:a.n||0})),{click:r=>{if(state.counties.length) state.las=[String(r.label)]; else state.counties=[String(r.label)]; renderFilters(); schedule()}})); dash.append(root)}
  function schedule(doRefresh=true){clearTimeout(timer); applyViewMode(); if(doRefresh) timer=setTimeout(refresh,250)}
  app.actions.register('collision-explorer-status',async()=>({where:where(),state,yearRange:[meta.minYear,meta.maxYear],definitionExpression:layer.definitionExpression,viewMode:state.heat?'heatmap':'points'}));
  try{await loadMeta(); fromURL(); enforceLA(); renderFilters(); applyViewMode(); await refresh();}catch(e){filters.replaceChildren(notice('danger','Data failed to load',e.message||String(e))); app.reportError(e)}
  app.onCleanup(()=>{clearTimeout(timer)});
}